extends Node
## Inventory REDACTEDload singleton.
## Keeps track of collected coins, persists the count to user://save.json,
## and emits `coin_changed` whenever the count changes (including on load).

signal coin_changed(new_count: int)

const SAVE_PATH := "user://save.json"

var count: int = 0


func _ready() -> void:
	# Restore any previously saved count on startup.
	load()


func _notification(what: int) -> void:
	# Persist the count when the user/application requests to quit.
	if what == NOTIFICATION_WM_CLOSE_REQUEST:
		save()


func add_coin() -> void:
	count += 1
	coin_changed.emit(count)
	# Keep the save file up to date as coins are collected.
	save()


func get_count() -> int:
	return count


func save() -> void:
	var file := FileAccess.open(SAVE_PATH, FileAccess.WRITE)
	if file == null:
		push_error("Inventory: could not open save file for writing: %s" % FileAccess.get_open_error())
		return
	var data := {"count": count}
	file.store_string(JSON.stringify(data))
	file.close()


func load() -> void:
	if not FileAccess.file_exists(SAVE_PATH):
		return
	var file := FileAccess.open(SAVE_PATH, FileAccess.READ)
	if file == null:
		push_error("Inventory: could not open save file for reading.")
		return
	var text := file.get_as_text()
	file.close()
	var parsed = JSON.parse_string(text)
	if typeof(parsed) != TYPE_DICTIONARY or not parsed.has("count"):
		push_warning("Inventory: save file is malformed, ignoring.")
		return
	count = int(parsed["count"])
	coin_changed.emit(count)

extends CharacterBody2D
## Player controlled with the arrow keys via the default ui_* input actions.

const SPEED := 300.0


func _physics_process(_delta: float) -> void:
	var dir_x := Input.get_axis("ui_left", "ui_right")
	var dir_y := Input.get_axis("ui_up", "ui_down")
	velocity = Vector2(dir_x, dir_y) * SPEED
	move_and_slide()

extends CanvasLayer
## Heads-up display. Updates a Label to show the current coin count whenever
## the Inventory REDACTEDload emits `coin_changed` (no per-frame polling).

@onready var label: Label = $Label


func _ready() -> void:
	Inventory.coin_changed.connect(_on_coin_changed)
	# Show the current value immediately (covers the count restored on load).
	_on_coin_changed(Inventory.get_count())


func _on_coin_changed(new_count: int) -> void:
	label.text = "Coins: " + str(new_count)

